def parse_metadata_block(body: str) -> dict:
    """Read the identity block back. Returns {} when absent.

    Uses the same bounds as :func:`upsert_metadata_block` so the reader and the
    writer agree on which block is authoritative: a stray or unfinished BEGIN
    quoted in prose (before or after the real block) must not contribute
    fields, or a task can inherit a parent, dependency, or identity from an
    example that was never actually written.
    """
    bounds = _metadata_bounds(body or "")
    if bounds is None:
        return {}
    start, end = bounds
    inner = body[start + len(METADATA_BEGIN) : end - len(METADATA_END)]
    fields: dict = {}
    for line in inner.splitlines():
        line = line.strip()
        if not line or line.startswith("<!--") or ":" not in line:
            continue
        key, _, value = line.partition(":")
        key = key.strip().lower()
        value = value.strip()
        if key == "depends-on":
            fields[key] = tuple(v.strip() for v in value.split(",") if v.strip())
        elif key in LINE_PER_ENTRY_KEYS:
            if value:  # a blank entry is not a step
                fields[key] = fields.get(key, ()) + (value,)
        elif value:
            fields[key] = value
    return fields
